BEGIN;

INSERT INTO journal_transaction (id, idempotency_key, currency)
VALUES (:journal_id, :key, :currency)
ON CONFLICT (idempotency_key) DO NOTHING;

INSERT INTO posting (journal_id, account_id, direction, amount)
VALUES
  (:journal_id, :debit_account, 'DEBIT', :amount),
  (:journal_id, :credit_account, 'CREDIT', :amount);

SELECT 1
FROM posting
WHERE journal_id = :journal_id
GROUP BY journal_id
HAVING SUM(CASE WHEN direction = 'DEBIT' THEN amount ELSE -amount END) = 0;
COMMIT;

