BEGIN;

UPDATE inventory_unit
SET held = held + :quantity, version = version + 1
WHERE flight_id = :flight_id
  AND held + confirmed + :quantity <= capacity
  AND version = :expected_version
RETURNING flight_id, held, version;

INSERT INTO seat_hold (hold_id, flight_id, customer_id, quantity, expires_at)
VALUES (:hold_id, :flight_id, :customer_id, :quantity, now() + interval '8 minutes');
COMMIT;

