BEGIN;

INSERT INTO checkout_inbox (idempotency_key, request_hash, state)
VALUES (:key, :request_hash, 'RECEIVED')
ON CONFLICT (idempotency_key) DO NOTHING;

UPDATE inventory
SET available = available - :qty, version = version + 1
WHERE sku_id = :sku_id
  AND available >= :qty
  AND version = :expected_version;
-- Require row_count = 1; otherwise reject or re-read the SKU.

INSERT INTO reservation (order_id, sku_id, quantity, state, expires_at)
VALUES (:order_id, :sku_id, :qty, 'HELD', now() + interval '10 minutes');

INSERT INTO outbox_event (event_id, aggregate_id, type, payload)
VALUES (:event_id, :order_id, 'StockReserved', :payload);
COMMIT;

BEGIN;

INSERT INTO event_inbox (event_id, consumer)
VALUES (:event_id, 'checkout')
ON CONFLICT (event_id, consumer) DO NOTHING;

UPDATE checkout_saga
SET state = :next_state, version = version + 1, updated_at = now()
WHERE checkout_id = :checkout_id
  AND version = :expected_version
  AND state = :expected_state;
-- Zero rows means duplicate, stale, or an unexpected transition.

