local remaining = redis.call('GET', KEYS[1])
if not remaining or tonumber(remaining) < tonumber(ARGV[1]) then
  return {0, remaining or '-1'}
end
redis.call('DECRBY', KEYS[1], ARGV[1])
return {1, remaining - ARGV[1]}

